250	/**
251	 * A whole project, in one transaction.
252	 *
253	 * The new project belongs to the caller's customer. There is no other option.
254	 *
255	 * **Only an `admin` creates one**, on the row of the permission table that says
256	 * so. The check is here as well as at the route, because signup provisions a
257	 * project before anybody has a context at all and the two paths must not be
258	 * able to drift apart on who may.
259	 *
260	 * What it writes is `insertProject`'s business and deliberately not this
261	 * function's: the project, its pointer to Egma's shared default persona, and its
262	 * `expected_behaviors` project grader. A project created here is therefore
263	 * indistinguishable from the one signup makes, which is the point — anything
264	 * less is a project that refuses the first test written in it, or one whose
265	 * completed simulations receive no expected-behavior grade.
266	 *
267	 * **The project and its expected-behavior grading are one transaction**, which
268	 * is the factory's doing rather than this function's: a project that existed
269	 * for even a moment with no project grader would produce completed simulations
270	 * with no expected-behavior grade, and "it depends when you looked" is not an
271	 * answer a trust product may give.
272	 */
273	export async function createProject(
274	  auth: AuthContext,
275	  input: NewProject,
276	): Promise<Project> {
277	  authorize(auth, "manage_projects", here(auth));
278	
279	  const name = input.name.trim();
280	  if (name === "") {
281	    throw new UnprocessableInputError("a project needs a name");
282	  }
283	
284	  const chosen = input.slug?.trim();
285	  const asked = chosen === undefined || chosen === "" ? undefined : slugFrom(chosen);
286	  const description = normalizedDescription(input.description);
287	
288	  for (let attempt = 1; ; attempt += 1) {
289	    const slug =
290	      asked ?? nextFreeSlug(slugFrom(name), await slugsLike(auth, slugFrom(name)));
291	
292	    try {
293	      return await db().transaction(async (tx) => {
294	        const projectId = newId("prj");
295	        await insertProject(tx, {
296	          projectId,
297	          organizationId: auth.organizationId,
298	          name,
299	          slug,
300	          description,
301	          revision: newId("rev"),
302	          createdBy: auth.userId,
303	        });
304	
305	        const [row] = await tx
306	          .select(COLUMNS)
307	          .from(project)
308	          .where(eq(project.id, projectId))
309	          .limit(1);
310	        if (row === undefined) throw new Error("the project was not written");

