 92	/**
 93	 * How long a claim may be held open, however patient the client says it is.
 94	 * Under the common 30s+ client timeouts and proxy idle windows, so a held
 95	 * claim always answers as a response rather than dying as a timeout.
 96	 */
 97	const LONGEST_HOLD_SECONDS = 25;
