 99	/** The hold for a client that did not say how long it would wait. */
100	const DEFAULT_HOLD_SECONDS = 15;
101	
102	/** How often a held claim re-asks the queue. The "about a second" promise. */
103	const RECHECK_MILLISECONDS = 1_000;
104	
105	/** Hard wall for queue wait, provider checks, assembly, and the response. */
106	const CLAIM_RESPONSE_MILLISECONDS = 28_000;
