108	/**
109	 * The most simulations one claim may take, mirrored from the module's own
110	 * cap. A larger ask is clamped rather than refused: a simulator declaring a
111	 * huge capacity is a configuration to serve at the platform's pace, not a
112	 * request that deserves to fail.
113	 */
114	const LARGEST_CLAIM_CAPACITY = 50;
