116	/**
117	 * The walls around one simulation, by modality — named constants matching
118	 * the contract's golden fixtures, so what the platform hands out and what
119	 * the fixtures teach cannot drift apart. A limit tripping ends a simulation
120	 * deliberately (`limit_reached`), which is never the agent failing; the
121	 * numbers bound egma's spend on a conversation going nowhere. Voice is
122	 * shorter than chat because every voice minute costs real speech synthesis
123	 * and transcription. Per-test limits are a future column on the test; these
124	 * are the platform's own.
125	 */
126	const SIMULATION_LIMITS = {
127	  chat: { max_duration_seconds: 600, max_turns: 60 },
128	  voice: { max_duration_seconds: 300, max_turns: 40 },
129	} as const;
