 15	 * an organization or project. The returned list contains only identities that
 16	 * this call inserted or changed; an unchanged boot returns an empty list.
 17	 */
 18	export async function seedPersonaLibrary(
 19	  catalog: readonly EgmaProvidedPersona[] = PERSONA_LIBRARY_CATALOG,
