 35	/**
 36	 * The trace store's own schema, applied in the background and never fatal.
 37	 *
 38	 * **This is the failure the durable boundary exists to remove.** A slow
 39	 * ClickHouse Cloud wake used to throw out of this module, so the process never
 40	 * reached `listen()` — and an egma that could have accepted evidence into
 41	 * object storage and drained it later instead accepted nothing, and took the
 42	 * hosted address down with it. Evidence is safe when it is durable in the
 43	 * bucket; ClickHouse is what happens next, and "next" is allowed to be late.
 44	 *
 45	 * So it runs beside the server rather than in front of it, its state is a
 46	 * reported component, and the drainer refuses to drain until it finishes —
 47	 * writing a segment into a schema still being built is how a good object
 48	 * becomes a retained defect for a reason that had nothing to do with it.
 49	 *
 50	 * It never settles into a terminal failure. A slow or unreachable store is
 51	 * retried with a doubling, capped backoff: the migrations are idempotent and one
 52	 * instance holds their lock, so a later attempt finishes what an earlier one
 53	 * could not — and until one does, the acceptance path keeps taking evidence and
 54	 * the drainer stands by. A process stuck in a `failed` state would hold the
 55	 * deployment's one drain claim behind a green health check for good, while a
 56	 * healthy sibling stood by forever.
 57	 *
 58	 * The `ingest` role skips it: that process never writes ClickHouse, and a role
 59	 * that only accepts evidence has no business applying somebody else's schema.
 60	 */
 61	type TraceStoreSchema =
 62	  | { readonly state: "skipped" }
 63	  | { readonly state: "migrating" }
 64	  | { readonly state: "ready"; readonly applied: readonly string[] };
 65	
 66	let traceSchema: TraceStoreSchema =
 67	  config.ingestion.role === "ingest"
 68	    ? { state: "skipped" }
