177	/**
178	 * The constraint a write broke, if it broke one.
179	 *
180	 * Which constraint it was is the difference between "somebody else already has
181	 * that name, try the next one" and "this person already has an organization,
182	 * stop" — so it is read rather than guessed at from the message. Drizzle may
183	 * hand the driver's error back wrapped, so both depths are looked at.
184	 */
185	function constraintViolated(error: unknown): string | undefined {
186	  for (let at: unknown = error, depth = 0; at !== undefined && at !== null && depth < 4; depth += 1) {
187	    if (typeof at !== "object") break;
188	    const carrier = at as { constraint?: unknown; cause?: unknown };
189	    if (typeof carrier.constraint === "string") return carrier.constraint;
190	    at = carrier.cause;
191	  }
192	  return undefined;
193	}
