195	/**
196	 * The hook the provider fires once an identity is written.
197	 *
198	 * A new project receives its shared default persona and seeded grader in the
199	 * same database transaction. The grader version owns its model selection;
200	 * provider credentials belong to the deployment.
201	 */
202	export function onIdentityCreated(): IdentityHooks["onIdentityCreated"] {
203	  return async (identity, intent) => {
204	    recordLanding(
205	      intent?.kind === "invitation"
206	        ? await join(identity, intent.token)
207	        : await provision(identity, intent),
208	    );
209	  };
210	}
211	
212	/**
213	 * An invited person, put in the organization that invited them.
214	 *
215	 * Nothing is created here: the organization, its projects and its first admin
216	 * already exist, and what this adds is one membership at the role the
217	 * invitation named. The default is `admin`, because that is the default for
218	 * everybody in this version — an organization whose second person cannot invite
219	 * a third is a two-person product.
220	 *
221	 * The refusals below are the same four the door check makes, and they are made
222	 * again because the door check and the write are not the same moment. Between
223	 * them a link can be spent by somebody else, which is exactly the race the
224	 * lock inside `acceptInvitation` exists for.
225	 */
226	async function join(
227	  identity: ExternalIdentity,
228	  token: string,
