132	   * whether the thing on the other end exists.
133	   */
134	  registerPlatformOperation(app, projectOperations.getProject, async (request, reply) => {
135	    const { auth } = requesterOf(request);
136	    const { projectId } = request.params as { projectId: string };
137	
138	    const projects = await listProjects(auth);
139	    const found = projects.find((project) => project.id === projectId);
140	    if (found === undefined) {
141	      return sendRefusal(
142	        reply,
143	        "project_outside_organization",
144	        projectOutsideOrganization(projectId),
145	      );
146	    }
147	
148	    return reply.send({
149	      ...described(found),
150	      mayManageProjects: permits(auth, "manage_projects", {
151	        organizationId: auth.organizationId,
152	        projectId: auth.projectId,
153	      }),
154	    });
155	  });
156	
157	  registerPlatformOperation(app, projectOperations.createProject, async (request, reply) => {
158	    const { auth } = requesterOf(request);
159	    const body = (request.body ?? {}) as Body;
160	
161	    if (auth.role !== "admin") {
162	      return refuseRole(reply, auth.role, "create a project");
163	    }
164	
165	    const unknown = unknownKeyIn(body, CREATE_KEYS, "a project");
