  7	/** Provider accounts for which this release can execute model work. */
  8	export const PROVIDER_ACCOUNTS = ["openai", "deepgram", "cartesia"] as const;
  9	export type ProviderAccount = (typeof PROVIDER_ACCOUNTS)[number];
 10	
 11	/**
 12	 * The current provider keys available to one unit of work.
 13	 *
 14	 * A bundle may be partial. A chat simulation only needs its LLM provider, and
 15	 * a deployment can add a provider before any persona selects it. The caller
 16	 * must fail the work if the provider it selected is absent.
 17	 */
 18	export type ProviderCredentialBundle = Readonly<
 19	  Partial<Record<ProviderAccount, string>>
 20	>;
 21	
 22	/**
 23	 * The operational source of provider credentials.
 24	 *
 25	 * `load` means "read the current bundle now". Implementations keep no bundle
 26	 * cache, so rotating the AWS secret changes the next unit of work without a
 27	 * process restart.
 28	 */
 29	export interface ProviderCredentialSource {
 30	  load(): Promise<ProviderCredentialBundle>;
 31	}
 32	
 33	/**
 34	 * The one deployment selector shared by the API and grader.
 35	 *
 36	 * Naming the Egma-specific secret id and region selects AWS Secrets Manager.
 37	 * Naming neither selects the self-host environment. A half-named AWS source is
 38	 * refused at startup. Generic AWS variables do not change this decision.
 39	 */
 40	export function providerCredentialSource(
 41	  environment: NodeJS.ProcessEnv,
 42	): ProviderCredentialSource {
 43	  const secretId = environment.EGMA_PROVIDER_CREDENTIALS_SECRET_ID?.trim() ?? "";
 44	  const region = environment.EGMA_PROVIDER_CREDENTIALS_REGION?.trim() ?? "";
 45	
 46	  if ((secretId === "") !== (region === "")) {
 47	    const missing = secretId === ""
 48	      ? "EGMA_PROVIDER_CREDENTIALS_SECRET_ID"
 49	      : "EGMA_PROVIDER_CREDENTIALS_REGION";
 50	    throw new Error(
 51	      `cloud provider credentials need both EGMA_PROVIDER_CREDENTIALS_SECRET_ID and EGMA_PROVIDER_CREDENTIALS_REGION; this deployment is missing ${missing}`,
 52	    );
 53	  }
 54	
 55	  return secretId === ""
 56	    ? environmentProviderCredentialSource(environment)
 57	    : secretsManagerProviderCredentialSource({ secretId, region });
 58	}
 59	
 60	/** The current provider bundle could not be read or decoded safely. */
 61	export class ProviderCredentialSourceUnavailableError extends Error {
 62	  constructor() {
 63	    super("the current model-provider credential bundle could not be read");
 64	    this.name = "ProviderCredentialSourceUnavailableError";
 65	  }
 66	}
 67	
 68	/** A unit of work selected a provider that the current bundle cannot fund. */
 69	export class ProviderCredentialMissingError extends Error {
 70	  readonly provider: string;
 71	
 72	  constructor(provider: string) {
 73	    const account = providerAccountFor(provider);
 74	    super(
 75	      account === undefined
 76	        ? `model provider ${provider} has no credential-account mapping in this release`
 77	        : `the current provider credential bundle has no ${account} key`,
 78	    );
 79	    this.name = "ProviderCredentialMissingError";
 80	    this.provider = provider;
 81	  }
 82	}
 83	
 84	/** One provider account named by the executable model catalog. */
 85	export function providerAccountFor(
 86	  provider: string,
 87	): ProviderAccount | undefined {
 88	  return PROVIDER_ACCOUNTS.find((account) => account === provider);
 89	}
 90	
 91	/** One selected provider's key, with no fallback to another account. */
 92	export function credentialFor(
 93	  bundle: ProviderCredentialBundle,
 94	  executionProvider: string,
 95	): string {
 96	  const account = providerAccountFor(executionProvider);
 97	  const key = account === undefined ? undefined : bundle[account];
 98	  if (key === undefined) throw new ProviderCredentialMissingError(executionProvider);
 99	  return key;
100	}
