102	const ENVIRONMENT_KEY: Readonly<Record<ProviderAccount, string>> = {
103	  openai: "EGMA_OPENAI_API_KEY",
104	  deepgram: "EGMA_DEEPGRAM_API_KEY",
105	  cartesia: "EGMA_CARTESIA_API_KEY",
106	};
107	
108	/** Provider keys supplied directly by a self-host operator. */
109	export function environmentProviderCredentialSource(
110	  environment: NodeJS.ProcessEnv,
111	): ProviderCredentialSource {
112	  return {
113	    async load(): Promise<ProviderCredentialBundle> {
114	      const credentials: Partial<Record<ProviderAccount, string>> = {};
115	      for (const account of PROVIDER_ACCOUNTS) {
116	        const value = environment[ENVIRONMENT_KEY[account]]?.trim();
117	        if (value) credentials[account] = value;
118	      }
119	      return credentials;
120	    },
121	  };
122	}
