382	      EGMA_SINGLE_ORGANIZATION: ${EGMA_SINGLE_ORGANIZATION:-true}
383	      EGMA_TRUST_PROXY: ${EGMA_TRUST_PROXY:-false}
384	      # The budget belongs to the organization rather than to a key, so
385	      # rotating a key does not reset it.
386	      EGMA_RATE_LIMIT_PER_MINUTE: ${EGMA_RATE_LIMIT_PER_MINUTE:-600}
387	      # Mail is optional and unset by default. With none, invitations hand
388	      # their link back to whoever sent them and signup asks for no
389	      # verification; setting this turns both around at once. It is never a
390	      # prerequisite for anything, including adding a second person.
391	      EGMA_SMTP_URL: ${EGMA_SMTP_URL:-}
392	      EGMA_MAIL_FROM: ${EGMA_MAIL_FROM:-}
393	      # Model choices are immutable persona and grader content. These are only
394	      # the current provider credentials. A self-host supplies the three keys
395	      # directly. Egma Cloud supplies a Secrets Manager id and region instead;
396	      # the API reads that object once while preparing each claimed simulation.
397	      EGMA_OPENAI_API_KEY: ${EGMA_OPENAI_API_KEY:-}
398	      EGMA_DEEPGRAM_API_KEY: ${EGMA_DEEPGRAM_API_KEY:-}
399	      EGMA_CARTESIA_API_KEY: ${EGMA_CARTESIA_API_KEY:-}
400	      EGMA_PROVIDER_CREDENTIALS_SECRET_ID: ${EGMA_PROVIDER_CREDENTIALS_SECRET_ID:-}
401	      EGMA_PROVIDER_CREDENTIALS_REGION: ${EGMA_PROVIDER_CREDENTIALS_REGION:-}
402	      # The optional shared carrier route. The API seals the SIP password in
403	      # the platform store; provider credentials use the variables above and
404	      # never enter platform settings.
405	      EGMA_PHONE_TRUNK_ADDRESS: ${EGMA_PHONE_TRUNK_ADDRESS:-}
406	      EGMA_PHONE_SOURCE_NUMBER: ${EGMA_PHONE_SOURCE_NUMBER:-}
407	      EGMA_PHONE_TRUNK_USERNAME: ${EGMA_PHONE_TRUNK_USERNAME:-}
408	      EGMA_PHONE_TRUNK_PASSWORD: ${EGMA_PHONE_TRUNK_PASSWORD:-}
409	      # An explicit ownership choice, separate from tenancy. `platform` seeds
410	      # a missing carrier route and then leaves the stored route alone.
411	      # `environment` makes the two-value source-IP route or four-value
412	      # credential route above authoritative on every start.
413	      EGMA_CARRIER_SETTINGS_SOURCE: ${EGMA_CARRIER_SETTINGS_SOURCE:-platform}
414	      # Egma platform telemetry, behind one flag that defaults to off — see
415	      # .env.example. Deliberately not the trace store: what customers send
570	      # variable through but does not restate that default, so a bare process
571	      # and a container cannot silently acquire different limits again.
572	      #
